// Get the extracted text and email metadata
const extractedData = $input.first().json;
const emailData = $('Download Resume').first().json;

// Extract email address - handle both object and string formats
let candidateEmail = '';
let candidateName = 'Unknown';

if (emailData.from && typeof emailData.from === 'object') {
  // Handle object format
  if (emailData.from.value && emailData.from.value[0]) {
    candidateEmail = emailData.from.value[0].address;
    candidateName = emailData.from.value[0].name || 'Unknown';
  } else if (emailData.from.text) {
    // Fallback to text format
    const emailMatch = emailData.from.text.match(/<(.+?)>/);
    candidateEmail = emailMatch ? emailMatch[1] : emailData.from.text;
  }
} else if (typeof emailData.from === 'string') {
  // Handle string format
  const emailMatch = emailData.from.match(/<(.+?)>/);
  candidateEmail = emailMatch ? emailMatch[1] : emailData.from;
}

// Get filename from attachments if available
let filename = 'resume.pdf';
if (emailData.attachments && emailData.attachments.length > 0) {
  filename = emailData.attachments[0].filename || filename;
}

return {
  json: {
    resume_text: extractedData.text,
    sender_email: candidateEmail,
    sender_name: candidateName,
    subject: emailData.subject,
    filename: filename,
    received_date: emailData.date || new Date().toISOString()
  }
};

const chainOutput = $input.first().json;
const preparedData = $('Prepare Resume Data').first().json;

let candidateData;

try {
  let jsonText = '';

  // Extract JSON from various possible formats
  if (chainOutput.output) {
    jsonText = typeof chainOutput.output === 'string' 
      ? chainOutput.output 
      : JSON.stringify(chainOutput.output);
  } else if (chainOutput.text) {
    jsonText = chainOutput.text;
  } else {
    jsonText = JSON.stringify(chainOutput);
  }

  // Remove markdown code blocks if present
  jsonText = jsonText.replace(/```json\n?/g, '').replace(/```\n?/g, '');

  // Extract JSON object
  const jsonMatch = jsonText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    candidateData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }

} catch (error) {
  // Fallback if parsing fails
  candidateData = {
    candidate_name: preparedData.sender_name,
    email: preparedData.sender_email,
    phone: "Not provided",
    skills: ["Unable to parse - Manual review needed"],
    years_of_experience: 0,
    education: "Unable to parse",
    recent_job_titles: ["Unable to parse"]
  };
}

// Use sender email if not found in resume
if (!candidateData.email || candidateData.email === '' || candidateData.email === 'email@example.com') {
  candidateData.email = preparedData.sender_email;
}

// Use sender name if not found
if (!candidateData.candidate_name || candidateData.candidate_name === 'Unknown' || candidateData.candidate_name === 'full name from resume') {
  candidateData.candidate_name = preparedData.sender_name;
}

return {
  json: {
    candidate_name: candidateData.candidate_name || preparedData.sender_name,
    email: candidateData.email,
    phone: candidateData.phone || "Not provided",
    skills: Array.isArray(candidateData.skills) ? candidateData.skills : [],
    years_of_experience: candidateData.years_of_experience || 0,
    education: candidateData.education || "Not provided",
    recent_job_titles: Array.isArray(candidateData.recent_job_titles) ? candidateData.recent_job_titles : [],
    original_subject: preparedData.subject,
    filename: preparedData.filename,
    received_date: preparedData.received_date
  }
};

