const chainOutput = $input.first().json;
const previousData = $('Add Job Requirements').first().json;

let scoreData;

try {
  let jsonText = '';

  // Extract JSON from various possible formats
  if (chainOutput.output) {
    jsonText = typeof chainOutput.output === 'string' 
      ? chainOutput.output 
      : JSON.stringify(chainOutput.output);
  } else if (chainOutput.text) {
    jsonText = chainOutput.text;
  } else {
    jsonText = JSON.stringify(chainOutput);
  }

  // Remove markdown code blocks if present
  jsonText = jsonText.replace(/```json\n?/g, '').replace(/```\n?/g, '');

  // Extract JSON object
  const jsonMatch = jsonText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    scoreData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }

} catch (error) {
  // Fallback scoring if AI fails
  scoreData = {
    overall_score: 50,
    skills_match_percentage: 50,
    experience_adequate: false,
    key_strengths: ["Resume received"],
    gaps: ["Unable to parse automatically"],
    recommendation: "Manual review required"
  };
}

return {
  json: {
    ...previousData,
    overall_score: scoreData.overall_score || 50,
    skills_match_percentage: scoreData.skills_match_percentage || 50,
    experience_adequate: scoreData.experience_adequate || false,
    key_strengths: Array.isArray(scoreData.key_strengths) ? scoreData.key_strengths : ["Not available"],
    gaps: Array.isArray(scoreData.gaps) ? scoreData.gaps : ["Not available"],
    recommendation: scoreData.recommendation || "Manual review required",
    timestamp: new Date().toISOString()
  }
};
